statements.text:
create table if not exists review.final_excel_mapping_import (
  import_id bigint generated by default as identity primary key,
  source_file text not null,
  source_sheet text not null,
  source_row_no integer not null,
  source_channel text not null,
  sellpia_sku text,
  channel_code text,
  channel_product_name text,
  channel_option_name text,
  match_tier text,
  match_score numeric,
  raw_data jsonb not null default '{}'::jsonb,
  imported_at timestamptz not null default now(),
  unique (source_file, source_sheet, source_row_no)
);
create index if not exists ix_final_excel_mapping_import_channel_code on review.final_excel_mapping_import(source_channel, channel_code);
create index if not exists ix_final_excel_mapping_import_sellpia_sku on review.final_excel_mapping_import(sellpia_sku);
create index if not exists ix_final_excel_mapping_import_tier on review.final_excel_mapping_import(source_channel, match_tier);

drop policy if exists "temp final mapping upload 20260728" on storage.objects;
drop policy if exists "temp final mapping delete 20260728" on storage.objects;
